{
  "name": "@workweave/router",
  "version": "0.2.37",
  "description": "One-command installer that points Claude Code, Codex, opencode, or pi at the Weave Router. For pi it also ships the routing extension, loaded via pi.extensions.",
  "bin": {
    "weave-router": "bin.js",
    "router": "bin.js"
  },
  "pi": {
    "extensions": [
      "./pi-router/src/index.ts"
    ],
    "skills": [
      "./pi-router/skills"
    ]
  },
  "files": [
    "bin.js",
    "windows.js",
    "install.sh",
    "uninstall.sh",
    "desktop-shim.js",
    "cc-statusline.sh",
    "codex-status.sh",
    "codex-toggle.sh",
    "registry.sh",
    "directives.tsv",
    "commands/",
    "codex-skills/",
    "skills/",
    "pi-router/",
    "README.md",
    "LICENSE",
    "NOTICE"
  ],
  "scripts": {
    "prepack": "node ./scripts/copy-installer.js"
  },
  "engines": {
    "node": ">=18"
  },
  "peerDependencies": {
    "@mariozechner/pi-agent-core": "*",
    "@mariozechner/pi-ai": "*",
    "@mariozechner/pi-coding-agent": "*",
    "@mariozechner/pi-tui": "*",
    "typebox": "*"
  },
  "peerDependenciesMeta": {
    "@mariozechner/pi-agent-core": {
      "optional": true
    },
    "@mariozechner/pi-ai": {
      "optional": true
    },
    "@mariozechner/pi-coding-agent": {
      "optional": true
    },
    "@mariozechner/pi-tui": {
      "optional": true
    },
    "typebox": {
      "optional": true
    }
  },
  "repository": {
    "type": "git",
    "url": "git+https://github.com/weave-os/router.git",
    "directory": "install/npm"
  },
  "homepage": "https://weaveos.com/products/router",
  "license": "Apache-2.0",
  "keywords": [
    "weave",
    "router",
    "claude",
    "claude-code",
    "anthropic",
    "codex",
    "opencode",
    "openai",
    "llm-router",
    "model-router",
    "ai-gateway",
    "llm-proxy",
    "pi",
    "pi-package"
  ],
  "dependencies": {
    "@decimalturn/toml-patch": "3.3.0",
    "isomorphic-git": "1.43.1",
    "smol-toml": "1.9.0"
  }
}

{
  "name": "@workweave/router-pi-extension",
  "private": true,
  "type": "module",
  "description": "The pi routing extension bundled into @workweave/router. NOT published separately: src/ is copied into the @workweave/router package at prepack and loaded via that package's pi.extensions. This manifest just marks the sources as ESM and declares the pi peer deps for local typecheck.",
  "scripts": {
    "typecheck": "tsc --project tsconfig.json"
  },
  "peerDependencies": {
    "@mariozechner/pi-agent-core": "*",
    "@mariozechner/pi-ai": "*",
    "@mariozechner/pi-coding-agent": "*",
    "@mariozechner/pi-tui": "*",
    "typebox": "*"
  },
  "devDependencies": {
    "@mariozechner/pi-agent-core": "npm:@earendil-works/pi-agent-core@0.83.0",
    "@mariozechner/pi-ai": "npm:@earendil-works/pi-ai@0.83.0",
    "@mariozechner/pi-coding-agent": "npm:@earendil-works/pi-coding-agent@0.83.0",
    "@mariozechner/pi-tui": "npm:@earendil-works/pi-tui@0.83.0",
    "@types/node": "24.13.3",
    "typebox": "1.3.25",
    "typescript": "5.9.3"
  },
  "packageManager": "pnpm@11.27.1"
}
